<?php
require __DIR__.'/ui.php';role(['admin','gerente','vendedor']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO leads(name,whatsapp,source,interest,stage,estimated_value,next_followup,notes)VALUES(?,?,?,?,?,?,?,?)")->execute([$_POST['name'],$_POST['whatsapp'],$_POST['source'],$_POST['interest'],$_POST['stage'],$_POST['estimated_value'],$_POST['next_followup'],$_POST['notes']]);go('leads.php');}if(isset($_GET['stage'],$_GET['id'])){$p->prepare("UPDATE leads SET stage=? WHERE id=?")->execute([$_GET['stage'],(int)$_GET['id']]);go('leads.php');}$rows=$p->query("SELECT * FROM leads ORDER BY id DESC")->fetchAll();$stages=['Novo lead','Contato feito','Orçamento enviado','Negociação','Fechado ganho','Fechado perdido'];page_head('Funil de vendas');?>
<div class="grid g2"><div class="card"><h2>Novo lead</h2><form method="post"><?=csrf_field()?><div class="grid g2"><div><label>Nome</label><input name="name" required></div><div><label>WhatsApp</label><input name="whatsapp"></div><div><label>Origem</label><select name="source"><option>Instagram</option><option>WhatsApp</option><option>Google</option><option>Indicação</option><option>Loja</option><option>Outro</option></select></div><div><label>Etapa</label><select name="stage"><?php foreach($stages as $s):?><option><?=e($s)?></option><?php endforeach;?></select></div><div><label>Interesse</label><input name="interest"></div><div><label>Valor estimado</label><input type="number" step=".01" name="estimated_value"></div><div><label>Próximo contato</label><input type="datetime-local" name="next_followup"></div></div><label>Notas</label><textarea name="notes"></textarea><button class="primary">Salvar lead</button></form></div><div class="card"><h2>Resumo</h2><?php foreach($stages as $s):?><p><?=e($s)?>: <b><?=count(array_filter($rows,fn($x)=>$x['stage']===$s))?></b></p><?php endforeach;?></div></div>
<div class="kanban"><?php foreach($stages as $stage):?><div class="column"><h3><?=e($stage)?></h3><?php foreach(array_filter($rows,fn($x)=>$x['stage']===$stage) as $x):?><div class="ticket"><b><?=e($x['name'])?></b><small><?=e($x['whatsapp'])?></small><small><?=e($x['interest'])?> • <?=money($x['estimated_value'])?></small><small>Próximo: <?=e($x['next_followup'])?></small><div class="actions"><?php foreach($stages as $s):if($s!==$stage):?><a class="btn" href="?id=<?=$x['id']?>&stage=<?=urlencode($s)?>"><?=e($s)?></a><?php endif;endforeach;?></div></div><?php endforeach;?></div><?php endforeach;?></div><?php page_foot();?>